customscripts.out:
{{#when {{greater_equal::{{chat_index}}::{{? {{lastmessageid}}-5}}}}}}
    {{settempvar::all_assets::{{module_assetlist::ANOM2}}}}

    {{#when {{contains::{{gettempvar::all_assets}}::$1_default}}}}
        {{#when {{contains::{{gettempvar::all_assets}}::$1_$2}}}}
            <div class="ib-asset-hover" style="background-image: url('{{raw::$1_$2}}');" tabindex="0"></div>
        {{/when}}

        {{#when {{equal::{{contains::{{gettempvar::all_assets}}::$1_$2}}::0}}}}
            <div class="ib-asset-hover" style="background-image: url('{{raw::$1_default}}');" tabindex="0"></div>
        {{/when}}
    {{/when}}
{{/when}}
